<div class="page-container"><div class="page-header"><div><h1 class="page-title">My Points</h1><p class="page-subtitle">Track your earnings across merchants</p></div></div>
<div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
<div class="lg:col-span-2"><div class="card overflow-hidden"><div class="p-4 border-b bg-surface-50 font-semibold text-surface-700">Points History</div>
<div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Merchant</th><th>Points</th><th>Type</th><th>Date</th></tr></thead>
<tbody id="pt-table"><tr><td colspan="4" class="text-center text-surface-400 py-8">Loading...</td></tr></tbody></table></div></div></div>
<div class="card p-6"><h2 class="font-bold text-surface-800 mb-4">Points Summary</h2><div id="pt-summary">Loading...</div></div></div></div>
<script>
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tb=n=>{n=n||'Basic';const m={Platinum:'bg-indigo-100 text-indigo-700',Gold:'bg-amber-100 text-amber-700',Silver:'bg-slate-100 text-slate-600',Bronze:'bg-orange-100 text-orange-700'};return '<span class="tier-badge px-2 py-0.5 rounded-full text-xs font-semibold '+(m[n]||'bg-surface-100 text-surface-600')+'">'+esc(n)+'</span>';};
fetch('/customer/api/points').then(r=>r.json()).then(d=>{if(d.success){let h='';d.history.forEach(t=>{const up=t.delta>=0;const st=(t.status&&t.status!=='approved')?' <span class="text-xs text-amber-600">('+esc(t.status.replace('_',' '))+')</span>':'';h+='<tr><td>'+esc(t.merchant)+'</td><td class="font-bold '+(up?'text-emerald-600':'text-red-500')+'">'+(up?'+':'-')+t.points+'</td><td>'+esc(t.type)+st+'</td><td class="text-surface-400 text-xs">'+esc(t.created_at)+'</td></tr>';});document.getElementById('pt-table').innerHTML=h;let s='<div class="space-y-3"><div><p class="text-sm text-surface-500">Total Points</p><p class="text-3xl font-bold text-bonus-600">'+Number(d.total_points).toLocaleString()+'</p></div><div><p class="text-sm text-surface-500">Merchants</p><p class="text-lg font-semibold">'+d.merchant_count+'</p></div><div><p class="text-sm text-surface-500">Tier</p><p class="text-lg font-semibold">'+tb(d.tier)+'</p></div>';s+='<div><p class="text-sm text-surface-500 mb-1">By merchant</p>';d.points.forEach(p=>{s+='<div class="flex justify-between text-sm"><span>'+esc(p.merchant)+' '+tb(p.tier_per_merchant)+'</span><span class="font-semibold">'+Number(p.points).toLocaleString()+'</span></div>'+(p.expires_on?'<div class="text-xs text-amber-600 text-right">expires '+esc(p.expires_on)+' if there is no activity</div>':'');});s+='</div></div>';document.getElementById('pt-summary').innerHTML=s;}});
</script>
@endsection
